-- Tags: long
-- long: many statements; over the time limit of the flaky check under the thread fuzzer.

-- Every path type read whole, as subcolumns from disk and extracted from the whole path, in a Wide part, a Compact part
-- with substream marks and a Compact part without them, compared with a Memory table of the type without SHARED filled
-- by the same expression. Each line prints the three equality flags and a sample value. The Map serialization versions
-- are pinned to basic: the bucketed Map inside a SHARED path has its own test.

SELECT '-- every path type: each subcolumn alone, two of one path, with the whole path and the whole column, functions rewritten to subcolumns';
DROP TABLE IF EXISTS sub_w; DROP TABLE IF EXISTS sub_cm; DROP TABLE IF EXISTS sub_cn; DROP TABLE IF EXISTS sub_mem;
CREATE TABLE sub_w (x UInt64, json JSON(SHARED arr Array(UInt8), SHARED n Nullable(String), SHARED t Tuple(p UInt64, q String), SHARED m Map(String, UInt64), SHARED d Dynamic, SHARED lc LowCardinality(String), SHARED v Variant(UInt64, String), SHARED lcn LowCardinality(Nullable(String)))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE sub_cm (x UInt64, json JSON(SHARED arr Array(UInt8), SHARED n Nullable(String), SHARED t Tuple(p UInt64, q String), SHARED m Map(String, UInt64), SHARED d Dynamic, SHARED lc LowCardinality(String), SHARED v Variant(UInt64, String), SHARED lcn LowCardinality(Nullable(String)))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 1, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE sub_cn (x UInt64, json JSON(SHARED arr Array(UInt8), SHARED n Nullable(String), SHARED t Tuple(p UInt64, q String), SHARED m Map(String, UInt64), SHARED d Dynamic, SHARED lc LowCardinality(String), SHARED v Variant(UInt64, String), SHARED lcn LowCardinality(Nullable(String)))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 0, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE sub_mem (x UInt64, json JSON(arr Array(UInt8), n Nullable(String), t Tuple(p UInt64, q String), m Map(String, UInt64), d Dynamic, lc LowCardinality(String), v Variant(UInt64, String), lcn LowCardinality(Nullable(String)))) ENGINE = Memory;
INSERT INTO sub_w SELECT number, concat('{"arr":', toString(range(number % 3)), ',"n":', if(number % 2 = 0, 'null', '"s"'), ',"t":{"p":', toString(number), ',"q":"q', toString(number % 3), '"},"m":{"k', toString(number % 2), '":', toString(number), '},"d":', if(number % 3 = 0, toString(number), concat('"d', toString(number), '"')), ',"lc":"lc', toString(number % 4), '","v":', if(number % 2 = 0, toString(number), concat('"v', toString(number), '"')), ',"lcn":', if(number % 5 = 0, 'null', concat('"n', toString(number % 3), '"')), '}') FROM numbers(20);
INSERT INTO sub_cm SELECT number, concat('{"arr":', toString(range(number % 3)), ',"n":', if(number % 2 = 0, 'null', '"s"'), ',"t":{"p":', toString(number), ',"q":"q', toString(number % 3), '"},"m":{"k', toString(number % 2), '":', toString(number), '},"d":', if(number % 3 = 0, toString(number), concat('"d', toString(number), '"')), ',"lc":"lc', toString(number % 4), '","v":', if(number % 2 = 0, toString(number), concat('"v', toString(number), '"')), ',"lcn":', if(number % 5 = 0, 'null', concat('"n', toString(number % 3), '"')), '}') FROM numbers(20);
