SELECT '-- the JSON inside a Tuple column';
DROP TABLE IF EXISTS tc_w; DROP TABLE IF EXISTS tc_cm; DROP TABLE IF EXISTS tc_cn; DROP TABLE IF EXISTS tc_mem;
CREATE TABLE tc_w (x UInt64, c Tuple(json JSON(SHARED a UInt64, SHARED arr Array(UInt8)))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE tc_cm (x UInt64, c Tuple(json JSON(SHARED a UInt64, SHARED arr Array(UInt8)))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 1, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE tc_cn (x UInt64, c Tuple(json JSON(SHARED a UInt64, SHARED arr Array(UInt8)))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 0, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE tc_mem (x UInt64, c Tuple(json JSON(a UInt64, arr Array(UInt8)))) ENGINE = Memory;
INSERT INTO tc_w SELECT number, tuple(CAST(concat('{"a":', toString(number), ',"arr":', toString(range(number % 3)), '}'), 'JSON(SHARED a UInt64, SHARED arr Array(UInt8))')) FROM numbers(20);
INSERT INTO tc_cm SELECT number, tuple(CAST(concat('{"a":', toString(number), ',"arr":', toString(range(number % 3)), '}'), 'JSON(SHARED a UInt64, SHARED arr Array(UInt8))')) FROM numbers(20);
INSERT INTO tc_cn SELECT number, tuple(CAST(concat('{"a":', toString(number), ',"arr":', toString(range(number % 3)), '}'), 'JSON(SHARED a UInt64, SHARED arr Array(UInt8))')) FROM numbers(20);
INSERT INTO tc_mem SELECT number, tuple(CAST(concat('{"a":', toString(number), ',"arr":', toString(range(number % 3)), '}'), 'JSON(SHARED a UInt64, SHARED arr Array(UInt8))')) FROM numbers(20);
