INSERT INTO sib_w SELECT number, tuple(CAST(concat('{"a":', toString(number), ',"b":"b', toString(number), '"}'), 'JSON(SHARED a UInt64, SHARED b String)'), concat('s', toString(number))), arrayMap(i -> tuple(CAST(concat('{"a":', toString(i), '}'), 'JSON(SHARED a UInt64)'), toUInt8(i)), range(number % 3)), if(number % 2 = 0, CAST(CAST(concat('{"a":', toString(number), '}'), 'JSON(SHARED a UInt64)'), 'Variant(JSON(SHARED a UInt64), String)'), CAST(concat('v', toString(number)), 'Variant(JSON(SHARED a UInt64), String)')), if(number % 2 = 0, CAST(CAST(concat('{"a":', toString(number), '}'), 'JSON(SHARED a UInt64)'), 'Dynamic'), CAST(concat('d', toString(number)), 'Dynamic')), map('k', CAST(concat('{"a":', toString(number + 100), '}'), 'JSON(SHARED a UInt64)')) FROM numbers(20);
